"""Brute-force liveness reference for tiny graphs (product-graph cycle search)."""
import sys, json

def predicates(req):
    inputs = req["inputs"]
    P = len(inputs); R = len(inputs[0]) if P else 0
    D = len(inputs[0][0]) if (P and R) else 0
    states = req["states"]
    exp = []
    for q in range(R):
        acc = [0]*D
        for r in range(P):
            for i in range(D):
                acc[i] += inputs[r][q][i]
        exp.append(acc)
    safe = []; done = []
    for s in states:
        ok = True
        for r in range(P):
            for q,v in enumerate(s["delivered"][r]):
                if v != exp[q]: ok = False
        for sl in s["slots"]:
            acc = [0]*D
            for r in sl["ranks"]:
                for i in range(D):
                    acc[i] += inputs[r][sl["seq"]][i]
            if acc != sl["sum"]: ok = False
        safe.append(ok)
        done.append(all(len(s["delivered"][r]) == R for r in range(P)))
    return safe, done

def fair_ok(S, L, enabled, fairness):
    for f in fairness:
        nm = f["action"]
        if f["mode"] == "weak":
            trig = all(s in enabled.get(nm,()) for s in S)
        else:
            trig = any(s in enabled.get(nm,()) for s in S)
        if trig and nm not in L:
            return False
    return True

def terminates_brute(req):
    states = req["states"]; edges = req["edges"]; start = req["start"]; fairness = req["fairness"]
    N = len(states)
    safe, done = predicates(req)
    if done[start]:
        return True, None
    adj = {i: [] for i in range(N)}
    for i,e in enumerate(edges):
        adj[e[0]].append((i, e[2], e[1]))
    enabled = {}
    for e in edges:
        enabled.setdefault(e[1], set()).add(e[0])
    fairnames = {f["action"] for f in fairness}
    seen = {start}; stack=[start]
    while stack:
        v = stack.pop()
        for _,w,_ in adj[v]:
            if not done[w] and w not in seen:
                seen.add(w); stack.append(w)
    # product-graph search from each candidate start u
    for u in sorted(seen):
        visited = set()
        work = [(u, frozenset([u]), frozenset())]
        visited.add((u, frozenset([u]), frozenset()))
        while work:
            v, S, L = work.pop()
            if v == u and len(S) > 1 or (v == u and L):
                # closed walk found (may be trivial); check fairness
                if fair_ok(set(S), set(L), enabled, fairness):
                    return False, (u, sorted(S), sorted(L))
            for eid, w, nm in adj[v]:
                if w not in seen: continue
                S2 = S | {w}
                L2 = L | ({nm} if nm in fairnames else set())
                key = (w, S2, L2)
                if key in visited: continue
                visited.add(key)
                work.append(key)
    # stutter case
    for s in sorted(seen):
        if all(s not in enabled.get(nm,()) for nm in fairnames):
            return False, (s, "stutter")
    return True, None

if __name__ == "__main__":
    for line in open(sys.argv[1]):
        req = json.loads(line)
        if req.get("op") != "audit": continue
        t, info = terminates_brute(req)
        print(json.dumps({"terminates": t, "info": info}))
